    assert_eq!(fifo_peek_err.kind(), AvErrorKind::InvalidArgument);
    assert_eq!(fifo_peek_err.code(), Some(AvErrorCode::EINVAL));
    let mut fifo_move_dst = Packet::default();
    packet_fifo.read_move(&mut fifo_move_dst).unwrap();
