    let mut dict = Dictionary::new();
    dict.set("title", "Clip").unwrap();
    dict.set("language", "eng").unwrap();
    dict.set("empty", "").unwrap();
    let packed_dict = packet_pack_dictionary(&dict);
    assert_eq!(
        packed_dict.as_slice(),
        b"title\0Clip\0language\0eng\0empty\0\0"
    );
    assert_eq!(packet_unpack_dictionary(&packed_dict).unwrap(), dict);
    let mut duplicate_dict = Dictionary::new();
    duplicate_dict
        .set_with_mode(
            "title",
            "first",
            MatchMode::CaseInsensitive,
            SetMode::AllowMultiple,
        )
        .unwrap();
    duplicate_dict
        .set_with_mode(
            "TITLE",
            "second",
            MatchMode::CaseInsensitive,
            SetMode::AllowMultiple,
        )
        .unwrap();
    duplicate_dict
        .set_with_mode(
            "artist",
            "Name",
            MatchMode::CaseInsensitive,
            SetMode::AllowMultiple,
        )
        .unwrap();
    let duplicate_packed_dict = packet_pack_dictionary(&duplicate_dict);
    assert_eq!(
        duplicate_packed_dict.as_slice(),
        b"title\0first\0TITLE\0second\0artist\0Name\0"
    );
    let duplicate_unpacked = packet_unpack_dictionary(&duplicate_packed_dict).unwrap();
    assert_eq!(duplicate_unpacked.len(), 2);
    assert_eq!(duplicate_unpacked.entries()[0].key(), "TITLE");
    assert_eq!(duplicate_unpacked.entries()[0].value(), "second");
    assert_eq!(duplicate_unpacked.entries()[1].key(), "artist");
    assert_eq!(duplicate_unpacked.entries()[1].value(), "Name");
    assert!(packet_pack_dictionary(&Dictionary::new()).is_empty());
    assert!(packet_unpack_dictionary(&[]).unwrap().is_empty());
    for invalid_dict in [
        b"title\0Clip".as_slice(),
        b"\0Clip\0".as_slice(),
        b"title\0".as_slice(),
        b"title\0Clip\0\0".as_slice(),
    ] {
        let err = packet_unpack_dictionary(invalid_dict).unwrap_err();
        assert_eq!(err.kind(), AvErrorKind::InvalidData);
        assert_eq!(err.code(), Some(AvErrorCode::INVALIDDATA));
    }
    match packet_unpack_dictionary(&typed_payload) {
        Ok(unpacked) => {
            for entry in unpacked.entries() {
                assert!(!entry.key().is_empty());
                assert!(!entry.key().as_bytes().contains(&0));
                assert!(!entry.value().as_bytes().contains(&0));
            }
            let repacked = packet_pack_dictionary(&unpacked);
            if unpacked.is_empty() {
                assert!(repacked.is_empty());
            } else {
                assert_eq!(repacked.last(), Some(&0));
                assert!(PacketStringMetadata::parse(&repacked).is_ok());
            }
        }
        Err(err) => assert_eq!(err.kind(), AvErrorKind::InvalidData),
    }

