    for (format, log2_chroma_w, log2_chroma_h, sample_bytes) in [
        (PixelFormat::Yuva420p9Le, 1usize, 1usize, 2usize),
        (PixelFormat::Yuva420p9Be, 1usize, 1usize, 2usize),
        (PixelFormat::Yuva422p9Le, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva422p9Be, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva444p9Le, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva444p9Be, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva420p10Le, 1usize, 1usize, 2usize),
        (PixelFormat::Yuva420p10Be, 1usize, 1usize, 2usize),
        (PixelFormat::Yuva422p10Le, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva422p10Be, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva444p10Le, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva444p10Be, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva422p12Le, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva422p12Be, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva444p12Le, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva444p12Be, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva420p16Le, 1usize, 1usize, 2usize),
        (PixelFormat::Yuva420p16Be, 1usize, 1usize, 2usize),
        (PixelFormat::Yuva422p16Le, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva422p16Be, 1usize, 0usize, 2usize),
        (PixelFormat::Yuva444p16Le, 0usize, 0usize, 2usize),
        (PixelFormat::Yuva444p16Be, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap10Le, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap10Be, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap12Le, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap12Be, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap14Le, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap14Be, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap16Le, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap16Be, 0usize, 0usize, 2usize),
        (PixelFormat::GbrapF16Le, 0usize, 0usize, 2usize),
        (PixelFormat::GbrapF16Be, 0usize, 0usize, 2usize),
        (PixelFormat::Gbrap32Le, 0usize, 0usize, 4usize),
        (PixelFormat::Gbrap32Be, 0usize, 0usize, 4usize),
        (PixelFormat::GbrapF32Le, 0usize, 0usize, 4usize),
        (PixelFormat::GbrapF32Be, 0usize, 0usize, 4usize),
    ] {
        let planar_storage =
            make_planar_alpha_sample_storage(log2_chroma_w, log2_chroma_h, sample_bytes);
        let mut planar_default_crop = Frame::video(
            VideoFrame::new_with_line_sizes(
                8,
                4,
                format,
                planar_storage.clone(),
                vec![64, 64, 64, 64],
            )
            .unwrap(),
        );
        planar_default_crop.set_crop_offsets(1, 0, 1, 1);
        let planar_before = planar_default_crop.clone();
        let default_error = planar_default_crop
            .apply_cropping(FrameCropFlags::NONE)
            .unwrap_err();
        assert_eq!(
            default_error.code().map(AvErrorCode::raw),
            Some(AvErrorCode::BUG.raw())
        );
        assert_eq!(planar_default_crop, planar_before);

        let mut planar_unaligned_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, planar_storage, vec![64, 64, 64, 64])
                .unwrap(),
        );
        planar_unaligned_crop.set_crop_offsets(1, 0, 1, 1);
        planar_unaligned_crop
            .apply_cropping(FrameCropFlags::UNALIGNED)
            .unwrap();
        let FrameData::Video(planar_unaligned_crop_video) = planar_unaligned_crop.data() else {
            panic!("constructed high-bit planar alpha unaligned crop frame changed variant");
        };
        assert_eq!(planar_unaligned_crop.crop(), FrameCrop::default());
        assert_eq!(planar_unaligned_crop_video.width(), 6);
        assert_eq!(planar_unaligned_crop_video.height(), 3);
        assert_eq!(planar_unaligned_crop_video.line_sizes(), &[64, 64, 64, 64]);
        assert_eq!(
            &planar_unaligned_crop_video.planes()[0][..6 * sample_bytes],
            &(0..6 * sample_bytes)
                .map(|column| 0x20 + sample_bytes as u8 + column as u8)
                .collect::<Vec<_>>()
        );
        assert_eq!(
            planar_unaligned_crop_video.planes()[1].len(),
            (6 >> log2_chroma_w) * (3 >> log2_chroma_h) * sample_bytes
        );
        assert_eq!(
            planar_unaligned_crop_video.planes()[2].len(),
            (6 >> log2_chroma_w) * (3 >> log2_chroma_h) * sample_bytes
        );
        assert_eq!(
            &planar_unaligned_crop_video.planes()[3][..6 * sample_bytes],
            &(0..6 * sample_bytes)
                .map(|column| {
                    0xf0_u8
                        .wrapping_add(sample_bytes as u8)
                        .wrapping_add(column as u8)
                })
                .collect::<Vec<_>>()
        );
    }

    let bitstream_row_bytes =
        |width: usize, bits_per_pixel: usize| (width * bits_per_pixel).div_ceil(8);
    let make_bitstream_crop_storage = |bits_per_pixel: usize| {
        let row_bytes = bitstream_row_bytes(8, bits_per_pixel);
        let mut storage = vec![0; 64 * 4];
        for row in 0..4 {
            for column in 0..row_bytes {
                storage[row * 64 + column] = (row * 16 + column) as u8;
            }
        }
        storage
    };
    for (format, bits_per_pixel) in [
        (PixelFormat::MonoWhite, 1usize),
        (PixelFormat::MonoBlack, 1usize),
        (PixelFormat::Rgb4, 4usize),
        (PixelFormat::Bgr4, 4usize),
    ] {
        let storage = make_bitstream_crop_storage(bits_per_pixel);
        let mut bitstream_default_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, vec![storage.clone()], vec![64]).unwrap(),
        );
        bitstream_default_crop.set_crop_offsets(1, 0, 1, 1);
        let before = bitstream_default_crop.clone();
        bitstream_default_crop
            .apply_cropping(FrameCropFlags::NONE)
            .unwrap();
        assert_ne!(bitstream_default_crop, before);
        assert_eq!(bitstream_default_crop.crop(), FrameCrop::new(1, 0, 1, 0));
        let FrameData::Video(bitstream_default_video) = bitstream_default_crop.data() else {
            panic!("constructed bitstream default crop frame changed variant");
        };
        assert_eq!(bitstream_default_video.width(), 7);
        assert_eq!(bitstream_default_video.height(), 4);
        assert_eq!(
            bitstream_default_video.planes()[0].len(),
            bitstream_row_bytes(7, bits_per_pixel) * 4
        );
        assert_eq!(
            &bitstream_default_video.planes()[0][..bitstream_row_bytes(7, bits_per_pixel)],
            (0..bitstream_row_bytes(7, bits_per_pixel) as u8)
                .collect::<Vec<_>>()
                .as_slice()
        );

        let mut bitstream_unaligned_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, vec![storage], vec![64]).unwrap(),
        );
        bitstream_unaligned_crop.set_crop_offsets(1, 0, 1, 1);
        bitstream_unaligned_crop
            .apply_cropping(FrameCropFlags::UNALIGNED)
            .unwrap();
        assert_eq!(bitstream_unaligned_crop.crop(), FrameCrop::new(1, 0, 1, 0));
        let FrameData::Video(bitstream_unaligned_video) = bitstream_unaligned_crop.data() else {
            panic!("constructed bitstream unaligned crop frame changed variant");
        };
        assert_eq!(bitstream_unaligned_video.width(), 7);
        assert_eq!(bitstream_unaligned_video.height(), 4);
        assert_eq!(
            bitstream_unaligned_video.planes()[0].len(),
            bitstream_row_bytes(7, bits_per_pixel) * 4
        );
    }

    let plane_visible_sample_bytes = |base: u8,
                                      start_row: usize,
                                      start_column_samples: usize,
                                      width_samples: usize,
                                      height: usize,
                                      sample_bytes: usize| {
        let start_column = start_column_samples * sample_bytes;
        let width_bytes = width_samples * sample_bytes;
        let mut data = Vec::with_capacity(width_bytes * height);
        for row in start_row..start_row + height {
            for column in start_column..start_column + width_bytes {
                data.push(base.wrapping_add((row * 16 + column) as u8));
            }
        }
        data
    };

    let make_semiplanar_crop_storage =
        |log2_chroma_w: usize,
         log2_chroma_h: usize,
         sample_bytes: (usize, usize),
         chroma_line_size: usize| {
            let mut luma = vec![0; 64 * 4];
            for row in 0..4 {
                for column in 0..8 * sample_bytes.0 {
                    luma[row * 64 + column] = 0x10 + (row * 16 + column) as u8;
                }
            }
            let chroma_height = 4 >> log2_chroma_h;
            let chroma_width_bytes = (8 >> log2_chroma_w) * sample_bytes.1;
            let mut chroma = vec![0; chroma_line_size * chroma_height];
            for row in 0..chroma_height {
                for column in 0..chroma_width_bytes {
                    chroma[row * chroma_line_size + column] = 0x80 + (row * 16 + column) as u8;
                }
            }
            vec![luma, chroma]
        };
    for (format, log2_chroma_w, log2_chroma_h) in [
        (PixelFormat::Nv12, 1usize, 1usize),
        (PixelFormat::Nv21, 1usize, 1usize),
        (PixelFormat::Nv16, 1usize, 0usize),
        (PixelFormat::Nv24, 0usize, 0usize),
        (PixelFormat::Nv42, 0usize, 0usize),
    ] {
        let line_sizes = if matches!(format, PixelFormat::Nv24 | PixelFormat::Nv42) {
            vec![64, 128]
        } else {
            vec![64, 64]
        };
        let storage =
            make_semiplanar_crop_storage(log2_chroma_w, log2_chroma_h, (1, 2), line_sizes[1]);
        let mut semiplanar_default_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage.clone(), line_sizes.clone())
                .unwrap(),
        );
        semiplanar_default_crop.set_crop_offsets(1, 0, 1, 1);
        semiplanar_default_crop
            .apply_cropping(FrameCropFlags::NONE)
            .unwrap();
        assert_eq!(semiplanar_default_crop.crop(), FrameCrop::default());
        let FrameData::Video(semiplanar_default_video) = semiplanar_default_crop.data() else {
            panic!("constructed semi-planar default crop frame changed variant");
        };
        assert_eq!(semiplanar_default_video.width(), 7);
        assert_eq!(semiplanar_default_video.height(), 3);
        assert_eq!(semiplanar_default_video.line_sizes(), line_sizes.as_slice());
        assert_eq!(
            &semiplanar_default_video.planes()[0][..7],
            &[0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26]
        );
        assert_eq!(
            semiplanar_default_video.planes()[1].as_slice(),
            plane_visible_sample_bytes(
                0x80,
                1 >> log2_chroma_h,
                0,
                7 >> log2_chroma_w,
                3 >> log2_chroma_h,
                2,
            )
            .as_slice()
        );

        let mut semiplanar_unaligned_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage.clone(), line_sizes.clone())
                .unwrap(),
        );
        semiplanar_unaligned_crop.set_crop_offsets(1, 0, 1, 1);
        semiplanar_unaligned_crop
            .apply_cropping(FrameCropFlags::UNALIGNED)
            .unwrap();
        assert_eq!(semiplanar_unaligned_crop.crop(), FrameCrop::default());
        let FrameData::Video(semiplanar_unaligned_video) = semiplanar_unaligned_crop.data() else {
            panic!("constructed semi-planar unaligned crop frame changed variant");
        };
        assert_eq!(semiplanar_unaligned_video.width(), 6);
        assert_eq!(semiplanar_unaligned_video.height(), 3);
        assert_eq!(
            &semiplanar_unaligned_video.planes()[0][..6],
            &[0x21, 0x22, 0x23, 0x24, 0x25, 0x26]
        );
        assert_eq!(
            semiplanar_unaligned_video.planes()[1].as_slice(),
            plane_visible_sample_bytes(
                0x80,
                1 >> log2_chroma_h,
                1 >> log2_chroma_w,
                6 >> log2_chroma_w,
                3 >> log2_chroma_h,
                2,
            )
            .as_slice()
        );

        let mut semiplanar_even_unaligned_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage, line_sizes).unwrap(),
        );
        semiplanar_even_unaligned_crop.set_crop_offsets(2, 0, 2, 2);
        semiplanar_even_unaligned_crop
            .apply_cropping(FrameCropFlags::UNALIGNED)
            .unwrap();
        let FrameData::Video(semiplanar_even_video) = semiplanar_even_unaligned_crop.data() else {
            panic!("constructed semi-planar even crop frame changed variant");
        };
        assert_eq!(semiplanar_even_video.width(), 4);
        assert_eq!(semiplanar_even_video.height(), 2);
        assert_eq!(
            semiplanar_even_video.planes()[1].as_slice(),
            plane_visible_sample_bytes(
                0x80,
                2 >> log2_chroma_h,
                2 >> log2_chroma_w,
                4 >> log2_chroma_w,
                2 >> log2_chroma_h,
                2,
            )
            .as_slice()
        );
    }

    for (format, log2_chroma_w, log2_chroma_h) in [
        (PixelFormat::Nv20Le, 1usize, 0usize),
        (PixelFormat::Nv20Be, 1usize, 0usize),
        (PixelFormat::P010Le, 1usize, 1usize),
        (PixelFormat::P010Be, 1usize, 1usize),
        (PixelFormat::P012Le, 1usize, 1usize),
        (PixelFormat::P012Be, 1usize, 1usize),
        (PixelFormat::P016Le, 1usize, 1usize),
        (PixelFormat::P016Be, 1usize, 1usize),
        (PixelFormat::P210Le, 1usize, 0usize),
        (PixelFormat::P210Be, 1usize, 0usize),
        (PixelFormat::P212Le, 1usize, 0usize),
        (PixelFormat::P212Be, 1usize, 0usize),
        (PixelFormat::P216Le, 1usize, 0usize),
        (PixelFormat::P216Be, 1usize, 0usize),
        (PixelFormat::P410Le, 0usize, 0usize),
        (PixelFormat::P410Be, 0usize, 0usize),
        (PixelFormat::P412Le, 0usize, 0usize),
        (PixelFormat::P412Be, 0usize, 0usize),
        (PixelFormat::P416Le, 0usize, 0usize),
        (PixelFormat::P416Be, 0usize, 0usize),
    ] {
        let line_sizes = if matches!(
            format,
            PixelFormat::P410Le
                | PixelFormat::P410Be
                | PixelFormat::P412Le
                | PixelFormat::P412Be
                | PixelFormat::P416Le
                | PixelFormat::P416Be
        ) {
            vec![64, 128]
        } else {
            vec![64, 64]
        };
        let storage =
            make_semiplanar_crop_storage(log2_chroma_w, log2_chroma_h, (2, 4), line_sizes[1]);

        let mut semiplanar_default_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage.clone(), line_sizes.clone())
                .unwrap(),
        );
        semiplanar_default_crop.set_crop_offsets(1, 0, 1, 1);
        let err = semiplanar_default_crop
            .apply_cropping(FrameCropFlags::NONE)
            .unwrap_err();
        assert_eq!(
            err.code().map(AvErrorCode::raw),
            Some(AvErrorCode::BUG.raw())
        );
        assert_eq!(semiplanar_default_crop.crop(), FrameCrop::new(1, 0, 1, 1));

        let mut semiplanar_unaligned_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage.clone(), line_sizes.clone())
                .unwrap(),
        );
        semiplanar_unaligned_crop.set_crop_offsets(1, 0, 1, 1);
        semiplanar_unaligned_crop
            .apply_cropping(FrameCropFlags::UNALIGNED)
            .unwrap();
        assert_eq!(semiplanar_unaligned_crop.crop(), FrameCrop::default());
        let FrameData::Video(semiplanar_unaligned_video) = semiplanar_unaligned_crop.data() else {
            panic!("constructed high-bit semi-planar unaligned crop frame changed variant");
        };
        assert_eq!(semiplanar_unaligned_video.width(), 6);
        assert_eq!(semiplanar_unaligned_video.height(), 3);
        assert_eq!(
            semiplanar_unaligned_video.line_sizes(),
            line_sizes.as_slice()
        );
        assert_eq!(
            semiplanar_unaligned_video.planes()[0].as_slice(),
            plane_visible_sample_bytes(0x10, 1, 1, 6, 3, 2).as_slice()
        );
        assert_eq!(
            semiplanar_unaligned_video.planes()[1].as_slice(),
            plane_visible_sample_bytes(
                0x80,
                1 >> log2_chroma_h,
                1 >> log2_chroma_w,
                6 >> log2_chroma_w,
                3 >> log2_chroma_h,
                4,
            )
            .as_slice()
        );

        let mut semiplanar_even_default_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage.clone(), line_sizes.clone())
                .unwrap(),
        );
        semiplanar_even_default_crop.set_crop_offsets(2, 0, 2, 2);
        let err = semiplanar_even_default_crop
            .apply_cropping(FrameCropFlags::NONE)
            .unwrap_err();
        assert_eq!(
            err.code().map(AvErrorCode::raw),
            Some(AvErrorCode::BUG.raw())
        );
        assert_eq!(
            semiplanar_even_default_crop.crop(),
            FrameCrop::new(2, 0, 2, 2)
        );

        let mut semiplanar_even_unaligned_crop = Frame::video(
            VideoFrame::new_with_line_sizes(8, 4, format, storage, line_sizes).unwrap(),
        );
        semiplanar_even_unaligned_crop.set_crop_offsets(2, 0, 2, 2);
        semiplanar_even_unaligned_crop
            .apply_cropping(FrameCropFlags::UNALIGNED)
            .unwrap();
        assert_eq!(semiplanar_even_unaligned_crop.crop(), FrameCrop::default());
        let FrameData::Video(semiplanar_even_video) = semiplanar_even_unaligned_crop.data() else {
            panic!("constructed high-bit semi-planar even crop frame changed variant");
        };
        assert_eq!(semiplanar_even_video.width(), 4);
        assert_eq!(semiplanar_even_video.height(), 2);
        assert_eq!(
            semiplanar_even_video.planes()[0].as_slice(),
            plane_visible_sample_bytes(0x10, 2, 2, 4, 2, 2).as_slice()
        );
        assert_eq!(
            semiplanar_even_video.planes()[1].as_slice(),
            plane_visible_sample_bytes(
                0x80,
                2 >> log2_chroma_h,
                2 >> log2_chroma_w,
                4 >> log2_chroma_w,
                2 >> log2_chroma_h,
                4,
            )
            .as_slice()
        );
    }

